// Cross-implementation parity for the link glyph transform: a Link drawn as a
// stretched geometry must land in exactly the same place here as it does in
// desktop GlyphViz.
//
// The fixture is generated by tools/dump_link_matrices.py, which runs the REAL
// desktop `link_glyph_matrix`, `is_glyph_link` and `local_z_span`. Both apps
// end in that one matrix, so this is the whole of what they have to agree
// about — everything above it (which object holds the matrix, how it is
// batched, what picks it) is each app's own business.
//
// The membership half matters as much as the numbers: LINK_LINE_GEOMETRIES is
// the feature's entire back-compat surface, and a scene whose 6,400 links sit
// on Point has to keep drawing lines rather than suddenly drawing 6,400 solid
// sprites' worth of stretched glyph.

import { describe, expect, it } from 'vitest'
import {
  isGlyphLink,
  linkGlyphMatrix,
  localZSpan,
  type Point3,
} from './linkGeometry'
import fixtureRaw from './fixtures/link_matrices.json?raw'

interface MatrixCase {
  name: string
  a: number[]
  b: number[]
  ratio: number
  geometry: number
  /** Row-major 4×4, or null for a degenerate edge. */
  matrix: number[][] | null
}

interface GeometryCase {
  geometry: number
  is_glyph_link: boolean
  local_z_span: number[]
}

const fixture = JSON.parse(fixtureRaw) as {
  cases: MatrixCase[]
  geometries: GeometryCase[]
}

/** Doubles on both sides, from the same closed-form expression. */
const TOL = 1e-12

describe('link glyph matrix parity with desktop GlyphViz', () => {
  it('has cases to compare', () => {
    expect(fixture.cases.length).toBeGreaterThan(10)
  })

  for (const entry of fixture.cases) {
    it(`${entry.name} matches the desktop matrix`, () => {
      const actual = linkGlyphMatrix(
        entry.a as unknown as Point3,
        entry.b as unknown as Point3,
        entry.ratio,
        entry.geometry,
      )
      if (entry.matrix === null) {
        // A zero-length edge has no axis to orient along, and "no sane
        // fallback" is itself the ported behaviour — the caller skips the draw
        // rather than emitting a NaN transform.
        expect(actual).toBeNull()
        return
      }
      expect(actual).not.toBeNull()
      for (let row = 0; row < 4; row++) {
        for (let col = 0; col < 4; col++) {
          // Desktop dumps row-major; this returns column-major (Three's own
          // layout, and the desktop's gl_matrix).
          expect(actual![col * 4 + row], `${entry.name} M[${row}][${col}]`).toBeCloseTo(
            entry.matrix[row][col],
            12,
          )
        }
      }
    })
  }

  it('agrees on which geometries stay line-drawn, and on every z span', () => {
    expect(fixture.geometries.length).toBe(29)
    for (const entry of fixture.geometries) {
      expect(isGlyphLink(entry.geometry), `is_glyph_link(${entry.geometry})`).toBe(
        entry.is_glyph_link,
      )
      const span = localZSpan(entry.geometry)
      expect(span[0], `z_min(${entry.geometry})`).toBeCloseTo(entry.local_z_span[0], 12)
      expect(span[1], `z_max(${entry.geometry})`).toBeCloseTo(entry.local_z_span[1], 12)
    }
  })

  it('is within TOL of the dump on an axis-aligned edge (a check on TOL itself)', () => {
    const entry = fixture.cases.find((c) => c.name === 'along_x')!
    const m = linkGlyphMatrix(entry.a as unknown as Point3, entry.b as unknown as Point3, entry.ratio, entry.geometry)!
    for (let row = 0; row < 4; row++) {
      for (let col = 0; col < 4; col++) {
        expect(Math.abs(m[col * 4 + row] - entry.matrix![row][col])).toBeLessThan(TOL)
      }
    }
  })
})
